package com.bananalab.lite;
import android.content.Context;import java.io.*;import java.util.*;import java.util.regex.*;import java.lang.reflect.*;import org.json.*;
/** Only these canonical, bounded functions may leave the compiler-only workspace. */
final class ProjectReplacementSpec{
 static String body(String source,String method){int[] span=JavaSourceEdit.method(source,method);return source.substring(span[0],span[1]).trim();}
 static JavaCurve curve(String body,boolean jump){Matcher m=Pattern.compile("(?s)^return\\s+(.+);$").matcher(body.trim());if(!m.matches())throw new IllegalArgumentException("Animación: un único return con una fórmula de t.");String expression=m.group(1).replaceAll("\\(\\s*float\\s*\\)","").replace("Math.PI","3.1415927f");JavaCurve curve=new JavaCurve(expression);if(Math.abs(curve.root.at(0))>.01f||Math.abs(curve.root.at(1))>.01f)throw new IllegalArgumentException("La animación debe empezar y terminar en cero.");for(int i=0;i<=1024;i++){float v=curve.root.at(i/1024f);if(Float.isNaN(v)||Float.isInfinite(v)||v<(jump?-40:-30)-.001f||v>(jump?0:30)+.001f)throw new IllegalArgumentException("Fórmula fuera del rango: salto -40 a0, balanceo -30 a30.");}return curve;}
 static JSONObject extract(Context c,String kind)throws Exception{JSONObject spec=new JSONObject().put("kind",kind).put("contract",1);if(kind.equals("animacion")){spec.put("jump",body(JavaProject.source(c,"AnimationProfile.java"),"jump")).put("sway",body(JavaProject.source(c,"AnimationProfile.java"),"sway"));}else if(kind.equals("chat"))spec.put("body",body(JavaProject.source(c,"ChatLanguage.java"),"socialReply"));else if(kind.equals("acciones"))spec.put("body",body(JavaProject.source(c,"ActionProfile.java"),"celebration"));else if(kind.equals("planificador"))spec.put("body",body(JavaProject.source(c,"PlannerProfile.java"),"rules"));else throw new IllegalArgumentException("Elegí animacion, chat, acciones o planificador.");sources(c,spec);return spec;}
 static String recipe(JSONObject spec)throws Exception{Matcher m=Pattern.compile("^return\\s+("+JavaTextPlan.LIT+")\\s*;$").matcher(spec.getString("body"));if(!m.matches())throw new IllegalArgumentException("celebration admite return de una secuencia literal.");String value=JavaTextPlan.decode(m.group(1));JavaPatchPolicy.sequence(value);return value;}
 static Map<String,String> sources(Context c,JSONObject spec)throws Exception{if(spec.getInt("contract")!=1)throw new IOException("Contrato de otra versión.");Map<String,String> out=new LinkedHashMap<>();out.put("BananaBehavior.java",JavaPatchPolicy.BASE);String kind=spec.getString("kind");if(kind.equals("planificador")){out.put("BananaProjectPatch.java",PlannerContract.source(PlannerContract.read(spec.getString("body"))));}else if(kind.equals("chat")){JavaTextPlan plan=JavaTextPlan.raw(spec.getString("body"));plan.controls();out.put("ChatLanguagePatched.java",plan.compiled(JavaMethodEditor.base(c)));}else{String methods;if(kind.equals("animacion")){JavaCurve jump=curve(spec.getString("jump"),true),sway=curve(spec.getString("sway"),false);methods="public static float jump(float t){return Math.max(-40f,Math.min(0f,"+jump.root.java()+"));} public static float sway(float t){return Math.max(-30f,Math.min(30f,"+sway.root.java()+"));}";}else if(kind.equals("acciones"))methods="public static String celebration(){return "+JavaTextPlan.literal(recipe(spec))+";}";else throw new IOException("Contrato desconocido.");out.put("BananaProjectPatch.java","package com.bananalab.patch; public final class BananaProjectPatch {"+methods+"}");}return out;}
 static Class<?> type(Context c,File jar,JSONObject spec)throws Exception{return OnDeviceJava.load(c,jar).getClassLoader().loadClass("com.bananalab.patch."+(spec.getString("kind").equals("chat")?"ChatLanguagePatched":"BananaProjectPatch"));}
 static int samples(JSONObject spec)throws Exception{return spec.getString("kind").equals("planificador")?PlannerContract.samples(PlannerContract.read(spec.getString("body"))):spec.getString("kind").equals("animacion")?2050:spec.getString("kind").equals("chat")?JavaTextPlan.raw(spec.getString("body")).samples().length:1;}
 static int check(Context c,File jar,JSONObject spec)throws Exception{sources(c,spec);Class<?> type=type(c,jar,spec);String kind=spec.getString("kind");if(kind.equals("planificador"))return PlannerContract.check(type.getMethod("plan",String.class,float[].class),PlannerContract.read(spec.getString("body")));if(kind.equals("chat"))return JavaMethodEditor.check(type.getMethod("socialReply",String.class),JavaTextPlan.raw(spec.getString("body")));if(kind.equals("acciones")){if(!recipe(spec).equals(type.getMethod("celebration").invoke(null)))throw new IOException("La secuencia compilada no coincide.");return 1;}for(String name:new String[]{"jump","sway"}){JavaCurve expected=curve(spec.getString(name),name.equals("jump"));Method method=type.getMethod(name,float.class);for(int i=0;i<=1024;i++){float t=i/1024f,v=((Number)method.invoke(null,t)).floatValue();if(Float.isNaN(v)||Float.isInfinite(v)||Math.abs(v-expected.root.at(t))>.001f)throw new IOException("La animación compilada no coincide.");}}return 2050;}
}
